/** Read-only evidence to help Nimo reconsider goals without replacing his choices.
 * Uses state and events already loaded for each model decision: zero D1 I/O.
 */
export type DecisionEvent={kind:string;action:string|null};
export function consecutivePassiveDecisions(events:readonly DecisionEvent[]):number{
  let count=0;
  // events are newest-first. Only Nimo's own decisions count; tool events
  // generated by successful actions terminate the passive run.
  for(const event of events){
    if(event.kind==="visitor"||event.kind==="reply")break;
    if(event.kind==="tool"||event.kind==="journal")break;
    if(event.kind!=="thought"&&event.kind!=="decision")continue;
    if(["THINK","OBSERVE","REMEMBER"].includes(event.action??""))count++;
    else break;
  }
  return count;
}

export type GoalReview={
  existingGoal:string|null;
  passiveDecisionStreak:number;
  evidence:string[];
  guidance:string;
};
/** A soft interpretation of verified circumstances, not an automatic goal-completion rule.
 * Never delete the goal, choose a tool, change curiosity, or create a task.
 */
export function goalReviewContext(
  goal:string|null,
  fullness:number,
  carriedFruits:readonly string[],
  recentEvents:readonly DecisionEvent[],
  hasPendingVisitor:boolean,
):GoalReview{
  const passiveDecisionStreak=consecutivePassiveDecisions(recentEvents);
  const evidence:string[]=[];
  if(goal && /\b(food|fullness|forag\w*|fruit|reserv\w*|eat\w*)\b/i.test(goal)){
    evidence.push("Current fullness: "+Math.round(fullness*100)+"%.");
    evidence.push("Fruit currently carried: "+carriedFruits.length+".");
    evidence.push("Carried fruit types: "+(carriedFruits.join(", ")||"none")+".");
    // Presence is factual, but it does not establish that this fruit
    // improves fullness. Nimo must use his verified memories to assess that.
    if(fullness>=0.6&&carriedFruits.length>0)
      evidence.push("Fullness is currently comfortable and fruit is carried, but inventory alone does not prove a usable food reserve. Evaluate known effects before deciding whether this goal is satisfied.");
  }
  if(goal && passiveDecisionStreak>=3 && !hasPendingVisitor)
    evidence.push("The last "+passiveDecisionStreak+" autonomous decisions were passive, without a new verified tool action.");
  let guidance="Your existing goal is optional and revisable. If the evidence indicates it has been satisfied, is no longer interesting, or is not actionable right now, consider marking it complete by returning goal:null. If it still matters, keep it. Do not claim success without confirmed evidence.";
  if(passiveDecisionStreak>=3&&!hasPendingVisitor)
    guidance+=" You have repeatedly paused. It is fine to remain still; avoid restating the same decision without new information. You may keep the quiet pause without an active task, or choose a genuinely interesting different direction. You are not required to be productive.";
  return {existingGoal:goal,passiveDecisionStreak,evidence,guidance};
}
